template <typename ParseContext>
FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
  auto it = ctx.begin();
  auto end = ctx.end();

  bool no_brackets = false;
  if (it != end && *it == 'n') {
    set_brackets({}, {});
    no_brackets = true;
    ++it;
  }

  // C++23 character range formatting (P2286): 's' formats a range of
  // characters as a string and '?s' as a debug string.
  if (it != end && detail::is_range_char_type<T>::value) {
    if (*it == 's') {
      is_string_format_ = true;
      ++it;
    } else if (*it == static_cast<Char>('?')) {
      ++it;
      if (it == end || *it != 's') report_error("invalid format specifier");
      is_string_format_ = true;
      is_debug_string_format_ = true;
      ++it;
    }
  }

  if (is_string_format_ && !no_brackets) {
    set_brackets(detail::string_literal<Char, '"'>{},
                 detail::string_literal<Char, '"'>{});
  }

  if (it != end && *it != '}') {
    if (*it != ':') report_error("invalid format specifier");
    ++it;
  } else if (!is_string_format_) {
    detail::maybe_set_debug_format(underlying_, true);
  }

  ctx.advance_to(it);
  return underlying_.parse(ctx);
}

